head.script:
scwin.gridView1_ongroupby = function(options) {
	scwin.groupbyFunc(options);
};
scwin.groupbyFunc = function(options) {
	options.groupbyHeader = [{
		colSpan: "5",
		inputType: "expression",
		expression: " toggle() + depthStr() + ' [ ' + count() + ' 건 ] ' ",
		align: "left"
	}];
	options.groupbyFooter = [{
			targetIndex: 2,
			colSpan: "2",
			inputType: "expression",
			expression: "SUM('sETC8')",
			align: "left"
		},
		{
			targetIndex: 3,
			colSpan: "2",
			inputType: "expression",
			expression: "SUM('sETC8')",
			align: "left"
		},
		{
			targetIndex: 6,
			colSpan: "2",
			inputType: "expression",
			expression: "SUM('sETC8')",
			align: "left"
		},
		{
			targetIndex: 7,
			colSpan: "2",
			inputType: "expression",
			expression: "SUM('sETC7')",
			displayFormatter: "countFormatFunction",
			align: "center"
		}
	];
	gridView1.groupby(options); //실제 groupby 실행
};
scwin.countFormatFunction = function(value) {
	return "총판매수량 : " + value + " 개 ";
};
